    'There is currently no research in progress. Click here to view lifeform techs.' => [
        'en' => 'There is currently no research in progress. Click here to view lifeform techs.',
        'ar' => 'Ahora mismo no se está investigando. Haz clic aquí para ir a la investigación de formas de vida.',
        'br' => 'Atualmente, não há pesquisas em andamento. Clique aqui para ver as técnicas de formas de vida.',
        'cz' => 'Momentálně neprobíhá žádný výzkum. Pro zobrazení technologií forem života klikni zde.',
        'de' => 'Momentan wird nicht geforscht. Klicke hier, um zur Forschung der Lebensform zu gelangen.',
        'dk' => 'Der er i øjeblikket ingen forskninger i gang. Klik her for at se Livsforms teks.',
        'es' => 'Ahora mismo no se está investigando. Haz clic aquí para ir a la investigación de formas de vida.',
